export fn interleavingstrings(a:?[*]const i64,n:usize)i64{if(a==null or n<3)return -1;const v=a.?[0..n];if(v[0]<0 or v[0]>32 or v[1]<0 or v[1]>32 or v[2]!=v[0]+v[1] or n!=@as(usize,@intCast(3+v[0]+v[1]+v[2])))return -1;for(v[3..])|x|{if(x<0 or x>127)return -1;}const m:usize=@intCast(v[0]);const k:usize=@intCast(v[1]);const s2=3+m;const s3=s2+k;var dp=[_]bool{false}**1089;dp[0]=true;for(0..m+1)|i|{for(0..k+1)|j|{if(i>0 and dp[(i-1)*33+j] and v[3+i-1]==v[s3+i+j-1])dp[i*33+j]=true;if(j>0 and dp[i*33+j-1] and v[s2+j-1]==v[s3+i+j-1])dp[i*33+j]=true;}}return if(dp[m*33+k])1 else 0;}
